  ('sadhuragiri', 'Sadhuragiri Malai', 'shiva', 'Shiva / Siddhars', 'Tamil Nadu', 'Watrap', 9.7272883, 77.6186383, 'A mystical siddhar mountain above the Western Ghats — 8 km trek to a Shiva shrine wrapped in monsoon mist.', 'Jun – Sep', 'https://lh3.googleusercontent.com/place-photos/AJRVUZOgKhpJ-WjMlkXxaWY1St7KDRQg2JCCu2Sw3X7NxWgBclKxtqQbQzys1C5JTvU_ugy6ZZv_ZZw1BmoxApov_IzUB47Qs0Rhlq0HJ0hWfTXiMbXOobU69jrJL0ANviK_8vMiQeQSE0dWC2WcTQ=s4800-w1600', ARRAY['trek','siddhar','monsoon']::text[], TRUE),
  ('agumbe', 'Agumbe', 'hill', NULL, 'Karnataka', 'Agumbe', 13.4965165, 75.0805657, 'The ''Cherrapunji of the South'' — king cobra country, Malgudi Days village and India''s finest west-coast sunset.', 'Jun – Sep', 'https://lh3.googleusercontent.com/place-photos/AJRVUZNwKi5fZJ-5m6iDCfjwO45GiRozefqGv7QHcqUyypcLNEZtKcF2TO4izSlj9RZca1g6tYAfHyPeJ4WD0_OcyVX_x3huMwgL4UhFILMNZ0X4UmL1KHZ5ZkXGnlAg5cueXHy7t2Q25gXq8iWnWQ=s4800-w1600', ARRAY['rainforest','king-cobra','sunset']::text[], TRUE),
  ('thiruparankundram', 'Thiruparankundram Murugan', 'murugan', 'Murugan', 'Tamil Nadu', 'Madurai', 9.8801051, 78.0713555, 'First of Murugan''s six sacred abodes (Arupadai Veedu) — a rock-cut cave temple where the god married Deivayanai.', 'Nov – Feb', 'https://lh3.googleusercontent.com/place-photos/AJRVUZPbEliLpUtjdZT53ttQmC7DJQl53swojMl5pzDt4ECRRCXZiXoTekD3uHdM4IizcMOaA4Q1e66dbBRPmxig0lOdDnDn37rl7ktuU-CA4Se3gu7GwsMBImz5mHzB9lQEZVSkANMYESQaOV43x5iml8N4Mw=s4800-w1600', ARRAY['arupadai','rock-cut','murugan']::text[], FALSE)
